-- Pending adjustment documents have their own history. Resolve them at the
-- same revision instead of relying on a bundle snapshot captured earlier.
CREATE OR REPLACE FUNCTION v32_snapshot_state(s jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN s ? 'inventory_state_code' THEN v32_inventory_state(s->>'physical_status',s->>'effective_reservation_id' IS NOT NULL OR s->>'sample_status'='SAMPLING' OR coalesce((s->>'pending_adjustment')::boolean,false),s->>'loading_workflow_state',CASE WHEN s->>'effective_loading_id' IS NOT NULL THEN s->>'loading_status' END) ELSE v32_inventory_state(s->>'physical_status',(s->>'reservation_id' IS NOT NULL AND coalesce(s->>'lot_workflow_state','')<>'CANCELLED') OR s->>'sample_status'='SAMPLING' OR coalesce((s->>'pending_adjustment')::boolean,false),s->>'loading_workflow_state',CASE WHEN s->>'loading_status' IN('DRAFT','LOADED') THEN s->>'loading_status' END) END $$;
CREATE FUNCTION v32_inventory_history(revision bigint) RETURNS TABLE(bundle_id uuid,state jsonb) LANGUAGE sql STABLE AS $$
 WITH latest AS(SELECT DISTINCT ON(h.bundle_id) h.bundle_id,h.state FROM inventory_history h WHERE h.revision_id<=revision ORDER BY h.bundle_id,h.revision_id DESC),effective AS(
 SELECT h.bundle_id,h.state||jsonb_build_object('pending_adjustment',CASE WHEN h.state->>'physical_status'='IN_STOCK' THEN EXISTS(SELECT 1 FROM adjustment_lines al JOIN(SELECT DISTINCT ON(document_id) document_id,data FROM document_history WHERE kind='stock_adjustments' AND revision_id<=revision ORDER BY document_id,revision_id DESC)d ON d.document_id=al.adjustment_id WHERE al.bundle_no=h.state->>'bundle_no' AND d.data->>'status' IN('DRAFT','PENDING')) ELSE false END) state FROM latest h),classified AS(SELECT e.bundle_id,e.state,v32_snapshot_state(e.state) code FROM effective e)
 SELECT c.bundle_id,c.state||jsonb_build_object('inventory_state_code',c.code,'business_status',v32_state_label(c.code)) FROM classified c;
$$;
